using Microsoft.ML;
using Microsoft.ML.Data;

var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

var mlContext = new MLContext(seed: 0);

// Load data
var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");
var dataView = mlContext.Data.LoadFromTextFile<CustomerData>(dataPath, hasHeader: true, separatorChar: ',');

// Build pipeline
var pipeline = mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerData.Region))
    .Append(mlContext.Transforms.Concatenate("Features", nameof(CustomerData.Age), nameof(CustomerData.Income), "RegionEncoded", nameof(CustomerData.PurchaseHistory)))
    .Append(mlContext.Transforms.NormalizeMinMax("Features"))
    .Append(mlContext.BinaryClassification.Trainers.FastTree(labelColumnName: "Label"));

// Map "Yes"/"No" to boolean label
var mappedData = mlContext.Transforms.CustomMapping<CustomerData, CustomerLabel>(
    (input, output) => output.Label = input.Churned == "Yes", contractName: null)
    .Fit(dataView).Transform(dataView);

var fullPipeline = mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerData.Region))
    .Append(mlContext.Transforms.Concatenate("Features", nameof(CustomerData.Age), nameof(CustomerData.Income), "RegionEncoded", nameof(CustomerData.PurchaseHistory)))
    .Append(mlContext.Transforms.NormalizeMinMax("Features"))
    .Append(mlContext.BinaryClassification.Trainers.FastTree(labelColumnName: "Label"));

var model = fullPipeline.Fit(mappedData);

// Prediction endpoint
var predictionEngine = mlContext.Model.CreatePredictionEngine<CustomerInput, ChurnPrediction>(model);

app.MapGet("/", () => "Churn Predictor API - POST to /predict with Age, Income, Region, PurchaseHistory");

app.MapPost("/predict", (CustomerInput input) =>
{
    var prediction = predictionEngine.Predict(input);
    return Results.Ok(new
    {
        WillChurn = prediction.PredictedLabel,
        Probability = prediction.Probability
    });
});

app.Run();

// Data models
